23	            return;
24	        }
25	        int members = 1; // this owner, not yet saved
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (householdId.equals(existing.getHouseholdId())) {
28	                members++;
29	            }
30	        }
31	        owner.setHouseholdSize(members);
