13	/**
14	 * Runs in the create-owner pipeline before {@link SaveOwner}. Assigns the owner's
15	 * {@code customerCode}, formatted {@code '<REGION>-<HASH8>'} where REGION is the region code shared
16	 * with {@link Owner#getLocality()} (derived from the postcode, falling back to the city, else
17	 * {@code 'UNKNOWN'}) and HASH8 is the first eight upper-case hex characters of a SHA-256 digest over
18	 * the normalized telephone concatenated with the last name (e.g. 'NSW-1A2B3C4D'). The sequence
19	 * numbers of the former city-and-last-name format are gone.
20	 *
21	 * <p>If the computed code collides with an existing owner's {@code customerCode}, it is
22	 * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it
23	 * unique (e.g. 'NSW-1A2B3C4D-2'). Mutates the built owner in place so later steps (membership
24	 * number, check digit, audit) derive from and store the assigned code.
25	 */
26	public class AssignCustomerCode {
27	
28	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
29	        String region = owner.getLocality();
30	        String hash8 = shaHex8(owner.getTelephone() + owner.getLastName());
31	        String base = region + "-" + hash8;
32	
33	        Set<String> existing = new HashSet<>();
34	        for (Owner other : ownerRepository.findAll()) {
35	            if (other.getCustomerCode() != null) {
36	                existing.add(other.getCustomerCode());
37	            }
38	        }
39	
40	        String code = base;
41	        for (int n = 2; existing.contains(code); n++) {
42	            code = base + "-" + n;
43	        }
44	        owner.setCustomerCode(code);
45	    }
46	
47	    /** First eight UPPER-case hex characters of SHA-256 over the UTF-8 bytes of {@code s}. */
48	    private static String shaHex8(String s) {
49	        try {
50	            byte[] digest = MessageDigest.getInstance("SHA-256")
51	                    .digest(s.getBytes(StandardCharsets.UTF_8));
52	            StringBuilder sb = new StringBuilder();
53	            for (byte b : digest) {
54	                sb.append(String.format("%02X", b));
55	                if (sb.length() >= 8) {
56	                    break;
57	                }
58	            }
59	            return sb.substring(0, 8);
60	        }
61	        catch (NoSuchAlgorithmException e) {
62	            throw new IllegalStateException("SHA-256 not available", e);
63	        }
64	    }
65	}
